import {CHART_STYLES} from './chart-layouts.js';
export function initStylePicker(onChoose){const select=document.getElementById('chart-style'),picker=document.getElementById('style-picker'),trigger=document.getElementById('style-trigger');select.innerHTML=CHART_STYLES.map(s=>`<option value="${s.id}">${s.name}</option>`).join('');
 const points={focus:[[20,20],[50,25],[80,20],[50,50]],network:[[15,20],[50,12],[82,28],[32,45],[65,50]],up:[[20,10],[80,10],[50,35],[50,55]],down:[[50,8],[50,25],[20,50],[80,50]],horizontal:[[10,30],[43,12],[43,48],[85,20],[85,48]],radial:[[50,30],[50,5],[80,30],[50,55],[20,30]],fan:[[50,52],[15,30],[35,10],[65,10],[85,30]],lifespans:[[15,10],[25,25],[40,40],[60,55]],arc:[[10,50],[35,50],[60,50],[85,50]],hourglass:[[20,8],[80,8],[50,30],[20,52],[80,52]]};
 const icon=s=>{const p=points[s.icon];return `<svg viewBox="0 0 100 65" aria-hidden="true">${p.slice(1).map((q,i)=>s.icon==='lifespans'?`<path d="M${q[0]},${q[1]} h30"/>`:s.icon==='arc'?`<path d="M10,50 Q${q[0]/2},${5+i*5} ${q[0]},50"/>`:`<path d="M${p[0][0]},${p[0][1]} L${q[0]},${q[1]}"/>`).join('')}${p.map((q,i)=>`<circle cx="${q[0]}" cy="${q[1]}" r="${i?3:5}"/>`).join('')}</svg>`;};
 picker.innerHTML=CHART_STYLES.map(s=>`<button data-style="${s.id}" aria-pressed="false">${icon(s)}<strong>${s.name}</strong><span>${s.hint}</span></button>`).join('');
 function choose(id,remember=true){if(!CHART_STYLES.some(s=>s.id===id))id='timeline';select.value=id;trigger.textContent=CHART_STYLES.find(s=>s.id===id).name+' ▾';picker.querySelectorAll('[data-style]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.style===id));picker.hidden=true;trigger.setAttribute('aria-expanded','false');if(remember)try{localStorage.setItem('family-chart-style',id);}catch{}onChoose(id);}
 picker.querySelectorAll('[data-style]').forEach(b=>b.onclick=()=>{choose(b.dataset.style);trigger.focus();});trigger.onclick=()=>{picker.hidden=!picker.hidden;trigger.setAttribute('aria-expanded',!picker.hidden);};select.onchange=()=>choose(select.value);document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!picker.hidden){picker.hidden=true;trigger.setAttribute('aria-expanded','false');trigger.focus();}});document.addEventListener('click',e=>{if(!picker.hidden&&!e.target.closest('.style-control')){picker.hidden=true;trigger.setAttribute('aria-expanded','false');}});let initial='timeline';try{initial=localStorage.getItem('family-chart-style')||initial;}catch{}choose(initial,false);
}
